const items = $input.all();

const seen = new Set();

function cleanText(value) {
  return String(value ?? "")
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function getPublisher(url) {
  const u = String(url || "").toLowerCase();

  if (u.includes("techcrunch.com")) return "TechCrunch";
  if (u.includes("xda-developers.com")) return "XDA Developers";
  if (u.includes("androidauthority.com")) return "Android Authority";
  if (u.includes("9to5google.com")) return "9to5Google";
  if (u.includes("androidpolice.com")) return "Android Police";
  if (u.includes("howtogeek.com")) return "How-To Geek";
  if (u.includes("makeuseof.com")) return "MakeUseOf";
  if (u.includes("producthunt.com")) return "Product Hunt";
  if (u.includes("alternativeto.net")) return "AlternativeTo";
  if (u.includes("arstechnica.com")) return "Ars Technica";

  return "Other";
}

const articles = [];

for (const item of items) {
  const d = item.json;

  const title = cleanText(d.title || d.name);

  const description = cleanText(
    d.contentSnippet ||
    d.content ||
    d.description ||
    d.summary
  ).slice(0, 800);

  const url = String(
    d.link ||
    d.url ||
    d.guid ||
    ""
  ).trim();

  const published =
    d.isoDate ||
    d.pubDate ||
    d.published ||
    d.date ||
    "";

  if (!title || !url) continue;

  if (seen.has(url)) continue;
  seen.add(url);

  articles.push({
    title,
    description,
    url,
    published,
    source: getPublisher(url)
  });
}

// Sort newest first
articles.sort((a, b) => {
  const aTime = new Date(a.published).getTime() || 0;
  const bTime = new Date(b.published).getTime() || 0;
  return bTime - aTime;
});

// Group by publisher
const groups = {};

for (const article of articles) {
  if (!groups[article.source]) {
    groups[article.source] = [];
  }

  groups[article.source].push(article);
}

const selected = [];
const used = new Set();

const publishers = [
  "TechCrunch",
  "XDA Developers",
  "Android Authority",
  "9to5Google",
  "Android Police",
  "How-To Geek",
  "MakeUseOf",
  "Product Hunt",
  "AlternativeTo",
  "Ars Technica"
];

// First pass: one article from each publisher
for (const publisher of publishers) {
  if (groups[publisher]?.length) {
    const article = groups[publisher][0];

    selected.push(article);
    used.add(article.url);
  }
}

// Second pass: add a second article from each publisher
for (const publisher of publishers) {
  if (selected.length >= 15) break;

  if (groups[publisher]?.length > 1) {
    const article = groups[publisher][1];

    if (!used.has(article.url)) {
      selected.push(article);
      used.add(article.url);
    }
  }
}

// Fill remaining slots with newest articles
for (const article of articles) {
  if (selected.length >= 15) break;

  if (!used.has(article.url)) {
    selected.push(article);
    used.add(article.url);
  }
}

// Sort final 15 by publication time
selected.sort((a, b) => {
  const aTime = new Date(a.published).getTime() || 0;
  const bTime = new Date(b.published).getTime() || 0;
  return bTime - aTime;
});

return [
  {
    json: {
      article_count: selected.length,
      total_articles_received: items.length,
      articles_after_cleaning: articles.length,
      sources_available: Object.fromEntries(
        Object.entries(groups).map(([source, list]) => [
          source,
          list.length
        ])
      ),
      sources_used: [...new Set(selected.map(a => a.source))],
      articles: selected
    }
  }
];
